package com.swingtrade.api.service;
import com.swingtrade.domain.LlmAnalysisResult; import com.swingtrade.domain.store.LlmAnalysisResultStore; import org.springframework.stereotype.Component; import java.time.LocalDate;
@Component public class LlmAnalysisGate {private final LlmAnalysisResultStore store; public LlmAnalysisGate(LlmAnalysisResultStore store){this.store=store;} public LlmVerdict evaluatePersisted(String symbol,LocalDate date){return store.findBySymbolAndDate(symbol,date).map(this::classify).orElseGet(LlmVerdict::pending);} private LlmVerdict classify(LlmAnalysisResult r){if(r.fallbackUsed())return new LlmVerdict(LlmVerdict.Action.ALLOW_GRACEFUL,"LLM fallback",null);String rec=r.recommendation()==null?"":r.recommendation().toUpperCase();if(rec.equals("SELL")||rec.equals("AVOID")||rec.equals("STRONG_SELL"))return new LlmVerdict(LlmVerdict.Action.SUPPRESS,rec,null);if(rec.equals("HOLD"))return new LlmVerdict(LlmVerdict.Action.FLAG_NEUTRAL,rec,null);if(rec.equals("BUY")||rec.equals("STRONG_BUY"))return new LlmVerdict(LlmVerdict.Action.ALLOW,rec,null);return new LlmVerdict(LlmVerdict.Action.ALLOW_GRACEFUL,"Unknown recommendation: "+rec,null);} public record LlmVerdict(Action action,String reason,String errorMessage){static LlmVerdict pending(){return new LlmVerdict(Action.PENDING,null,null);} public enum Action{PENDING,SUPPRESS,FLAG_NEUTRAL,ALLOW,ALLOW_GRACEFUL}}}
